def tricky(tokens):
    lp = torch.full((6,), -100.0)
    if len(tokens) == 1:
        lp[1] = -1.0; lp[2] = -0.5
    elif tokens[-1] == 1:
        lp[5] = 0.0
    elif tokens[-1] == 2:
        lp[5] = -10.0
    else:
        lp[5] = 0.0
    return lp
