            if rng.random() < 0.3:
                delta["content"] = None
            deltas.append(delta)
        acc = {}
        for d in deltas:
            {fn}(acc, d)
        want = {"role": "assistant", "content": content}
        if calls:
            want["tool_calls"] = calls
        assert acc == want, (seed, trial, deltas, acc, want)

