    raw = []
    for name, depth, first, last in spans(samples):
        if last - first + 1 >= k:
            raw.append((first + k - 1, "start", samples[first + k - 1][0], name, depth))
            if last + k < len(samples):
                raw.append((last + k, "end", samples[last + k][0], name, depth))
    return ordered(raw)

