    for cut in range(size):
        yield lambda data, cut=cut: data[:cut]
    for cut in range(1, size + 1):
        yield lambda data, cut=cut: bytes(cut)
    for i in range(size):
        yield lambda data, i=i: data[:i] + bytes([data[i] ^ 0xFF]) + data[i + 1:]

