def history(fs, n):
    store = {fn}(fs, log=True)
    for i in range(n):
        store.put("x", str(i))
        store.put(f"tmp{i % 7}", "y" * 20)
        store.delete(f"tmp{i % 7}")
    store.put("x", "final")
    store.put("y", "keep")
    store.put("", "")
    return store

