                    return False
        self.nodes = after
        self.make_dirs(d[:-1])
        return True
    def mv(self, src, dst):
        return self.transfer(src, dst, False)
    def cp(self, src, dst):
        return self.transfer(src, dst, True)
    def rm(self, path):
        p = parts_of(path)
